"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface MicrochipIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface MicrochipIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const MicrochipIcon = forwardRef<MicrochipIconHandle, MicrochipIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const pinVariants: Variants = {
   normal: { opacity: 1 },
   animate: (i: number) => ({
    opacity: [1, 0.2, 1],
    transition: {
     duration: 0.4 * duration,
     ease: "easeInOut",
     delay: i * 0.025 * duration,
    },
   }),
  };

  const bitVariants: Variants = {
   normal: { x: 0 },
   animate: (i: number) => ({
    x: [0, 1.5, -0.4, 0],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     times: [0, 0.35, 0.7, 1],
     delay: i * 0.08 * duration,
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path d="M10 7h4" variants={bitVariants} custom={0} />
      <m.path d="M10 12h4" variants={bitVariants} custom={1} />
      <m.path d="M10 17h4" variants={bitVariants} custom={2} />
      <m.path d="M4 6h2" variants={pinVariants} custom={0} />
      <m.path d="M18 6h2" variants={pinVariants} custom={1} />
      <m.path d="M4 12h2" variants={pinVariants} custom={2} />
      <m.path d="M18 12h2" variants={pinVariants} custom={3} />
      <m.path d="M4 18h2" variants={pinVariants} custom={4} />
      <m.path d="M18 18h2" variants={pinVariants} custom={5} />
      <rect x="6" y="2" width="12" height="20" rx="2" />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

MicrochipIcon.displayName = "MicrochipIcon";
export { MicrochipIcon };
